INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4301, 'Numbers 30:7', 'Numbers', 30, 7, '&nbsp;نو هغې چې کومه منښته منلې وى يا يې وعده کړې وى نو هغه به خامخا پوره کوى خو کۀ د هغې خاوند ترې نه خبر شى او څۀ اِعتراض وکړى نو هغه به نۀ پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4302, 'Numbers 30:8', 'Numbers', 30, 8, '&nbsp;خو کۀ خاوند يې خبر شى او د هغه وعدې پوره کولو نه يې منع کړى، نو د هغې دپاره دا ضرورى نۀ ده چې دا وعده پوره کړى. مالِک خُدائ به هغه معاف کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4303, 'Numbers 30:9', 'Numbers', 30, 9, '&nbsp;يوه کونډه يا طلاقه ښځه به خامخا خپل قسم پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4304, 'Numbers 30:10', 'Numbers', 30, 10, '&nbsp;کۀ يوه وادۀ شوې ښځه يوه منښته ومنى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4305, 'Numbers 30:11', 'Numbers', 30, 11, '&nbsp;نو هغه به خامخا هغه هر څۀ کوى چې هغې منښته منلې وى. کۀ خاوند يې خبر شى او څۀ اِعتراض وکړى نو بيا به يې نۀ پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4306, 'Numbers 30:12', 'Numbers', 30, 12, '&nbsp;خو کۀ خاوند يې خبر شى او هغه د وعدې پوره کولو نه منع کړى، نو ضرورى نۀ ده چې دا وعده پوره کړى. مالِک خُدائ به هغه معاف کړى، ځکه چې د هغې خاوند د دې قسم د پوره کولو نه منع کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4307, 'Numbers 30:13', 'Numbers', 30, 13, '&nbsp;د هغې خاوند دا حق لرى چې هغې له د دې لوظُونو پوره کولو اجازت ورکړى يا ورنۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4308, 'Numbers 30:14', 'Numbers', 30, 14, '&nbsp;خو کۀ، د ورځې د تېرېدو نه پس، هغه د دې قسم نه خبر شى او څۀ اِعتراض ونۀ کړى، نو هغه دې خامخا هغه هر څۀ وکړى چې د څۀ يې قسم يا وعده کړې وى. ځکه چې په کومه ورځ هغه خبر شو نو څۀ اِعتراض يې ونۀ کړو نو قسم دې خامخا پوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4309, 'Numbers 30:15', 'Numbers', 30, 15, '&nbsp;خو کۀ وروستو يې خاوند د خپلې خبرې نه واوړېدو، نو د دې قسم ماتولو سزا به د هغې خاوند ته مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4310, 'Numbers 30:16', 'Numbers', 30, 16, '&nbsp;دا هغه اصُول دى کوم چې مالِک خُدائ موسىٰ ته وښودل کوم چې د هغه قسمونو د خوړلو په حقله دى چې يوه پېغله چې د خپل پلار په کور کښې اوسيږى يا يې يوه وادۀ شوې ښځه وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4311, 'Numbers 31:1', 'Numbers', 31, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4312, 'Numbers 31:2', 'Numbers', 31, 2, '&nbsp;”د بنى اِسرائيلو سره چې ميديانيانو څۀ کړى وُو د هغې بدل ترې نه واخله. کله چې تۀ دا وکړې نو مړ به شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4313, 'Numbers 31:3', 'Numbers', 31, 3, '&nbsp;نو موسىٰ خلقو ته وفرمائيل، ”د جنګ دپاره تيار شئ، چې تاسو په ميديانيانو حمله وکړئ او د هغوئ نه د مالِک خُدائ بدله واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4314, 'Numbers 31:4', 'Numbers', 31, 4, '&nbsp;د بنى اِسرائيلو د هرې قبيلې نه زر کسان د جنګ دپاره ولېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4315, 'Numbers 31:5', 'Numbers', 31, 5, '&nbsp;نو د هرې قبيلې نه زر زر سړى خوښ کړے شول، دولس زره سړو د جنګ دپاره ملا وتړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4316, 'Numbers 31:6', 'Numbers', 31, 6, '&nbsp;موسىٰ هغوئ د اِلى‌عزر اِمام زوئ فينحاس د مشرۍ لاندې جنګ له ولېږل، هغۀ د مقدسو سامانونو او د بيګلو ذمه وارى واخستله چې د اِشارو دپاره غږولے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4317, 'Numbers 31:7', 'Numbers', 31, 7, '&nbsp;هغوئ په ميديانيانو باندې حمله وکړه، هم هغه شان چې مالِک خُدائ حُکم کړے وو او ټول سړى يې ووژل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4318, 'Numbers 31:8', 'Numbers', 31, 8, '&nbsp;سره د پينځو ميديانيانو بادشاهانو چې دا وُو، يعنې ايوى، رِقم، صور، حُور او رِبع. هغوئ د بعور زوئ بلعام هم ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4319, 'Numbers 31:9', 'Numbers', 31, 9, '&nbsp;بنى اِسرائيلو د ميديانيانو ښځې او ماشومان ونيول، د هغوئ څاروى او رَمې يې بوتلې، ټول مال يې ورله لوټ کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4320, 'Numbers 31:10', 'Numbers', 31, 10, '&nbsp;او د هغوئ ټول ښارونه او خېمې يې وسوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4321, 'Numbers 31:11', 'Numbers', 31, 11, '&nbsp;هغوئ ترې نه هغه ټول مالِ غنيمت يوړو چې کوم يې نيولے وو، په دې کښې قېديان او ځناور هم وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4322, 'Numbers 31:12', 'Numbers', 31, 12, '&nbsp;او موسىٰ، اِلى‌عزر او د بنى اِسرائيلو ټول قوم له يې راوړل، چې هغوئ د اُردن سيند نه پورې يريحو ته مخامخ د موآب په مېدانونو کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4323, 'Numbers 31:13', 'Numbers', 31, 13, '&nbsp;موسىٰ، اِلى‌عزر او د قوم ټول مشران لاړل چې د کېمپ نه بهر د لښکر سره مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4324, 'Numbers 31:14', 'Numbers', 31, 14, '&nbsp;موسىٰ هغه آفسرانو ته سخت غصه وو، چې د سلګونو او زرګونو مشران وُو او د جنګ نه راواپس شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4325, 'Numbers 31:15', 'Numbers', 31, 15, '&nbsp;موسىٰ د هغوئ نه تپوس وکړو، ”تاسو دا ټولې ښځې ولې ژوندۍ پرېښودلې دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4326, 'Numbers 31:16', 'Numbers', 31, 16, '&nbsp;ياد ساتئ چې زناناؤ د بلعام په نصيحت عمل وکړو او په فعور کښې يې خلق د مالِک خُدائ نافرمانه کړل، او د دوئ په وجه د مالِک خُدائ په خلقو وبا راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4327, 'Numbers 31:17', 'Numbers', 31, 17, '&nbsp;نو اوس ټول هلکان ووژنئ او ورسره هغه ښځې هم ووژنئ چې پېغلې نۀ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4328, 'Numbers 31:18', 'Numbers', 31, 18, '&nbsp;خو د ځان دپاره هغه ټولې جينکۍ او ښځې ژوندۍ پرېږدئ چې نا وادۀ کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4329, 'Numbers 31:19', 'Numbers', 31, 19, '&nbsp;نو ستاسو هر يو کس چې څوک يې وژلے وى يا د يو مړى سره لګېدلے وى نو هغه به اووۀ ورځې د خېمو نه بهر ايساريږى. په درېمه او په اوومه ورځ به خپل ځانونه او هغه ښځې پاکې کړئ چې کومې مو نيولې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4330, 'Numbers 31:20', 'Numbers', 31, 20, '&nbsp;تاسو به خپلې ټولې کپړې او څرمنې، د چېلو ټولې وړۍ او د لرګى نه جوړ شوے هر څيز پاک کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4331, 'Numbers 31:21', 'Numbers', 31, 21, '&nbsp;اِلى‌عزر اِمام هغه سړو ته وفرمائيل کوم چې د جنګ نه راواپس شوى وُو، ”دا هغه اصُول دى چې مالِک خُدائ يې موسىٰ ته حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4332, 'Numbers 31:24', 'Numbers', 31, 24, '&nbsp;په اوومه ورځ به تاسو خامخا خپلې جامې وينځئ، بيا به تاسو پاک شئ او خېمو ته به ننوتلے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4333, 'Numbers 31:25', 'Numbers', 31, 25, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4334, 'Numbers 31:26', 'Numbers', 31, 26, '&nbsp;”تۀ او اِلى‌عزر د قوم د نورو مشرانو سره، هغه ټول څيزونه وشمېرئ چې کوم نيولے شوى دى، سره د قېديانو او ځناورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4335, 'Numbers 31:27', 'Numbers', 31, 27, '&nbsp;څۀ څيز چې نيولے شوے وى هغه په دوه برابرو حِصو کښې تقسيم کړئ، يوه حِصه به د هغو کسانو دپاره وى چې جنګ له تلى وى او يوه حِصه به د نور قوم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4336, 'Numbers 31:28', 'Numbers', 31, 28, '&nbsp;د هغه کسانو د حِصې نه چې جنګ له تلى وى، د هر پينځۀ سوو قېديانو، څاروو، خرو، ګډو او د چېلو نه په هر پينځۀ سوو کښې يو د مالِک خُدائ دپاره جدا کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4337, 'Numbers 31:29', 'Numbers', 31, 29, '&nbsp;دا اِلى‌عزر اِمام له د مالِک خُدائ دپاره د خاص نذرانې په توګه ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4338, 'Numbers 31:30', 'Numbers', 31, 30, '&nbsp;کومه حِصه چې نورو خلقو له ورکړے شوى وى د هغې نه، د هر پنځوسو قېديانو، څاروو، خرو، ګډو او د چېلو نه د هر پنځوسو نه يو جدا کړئ. دا هغه ليويانو له ورکړئ چې د مالِک خُدائ د خېمې د خيال ساتلو ذمه وار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4339, 'Numbers 31:31', 'Numbers', 31, 31, '&nbsp;موسىٰ او اِلى‌عزر هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4340, 'Numbers 31:41', 'Numbers', 31, 41, '&nbsp;نو موسىٰ اِلى‌عزر له دا برخه د مالِک خُدائ دپاره د خاص برخې په توګه ورکړه، هم هغه شان چې څنګه مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4341, 'Numbers 31:47', 'Numbers', 31, 47, '&nbsp;د دې حِصې نه موسىٰ د هر يو پنځوسو قېديانو او ځناورو نه يو يو واخستلو او چې څنګه مالِک خُدائ فرمائيلى وُو هم هغه شان يې دا ليويانو له ورکړل چې هغوئ د مالِک خُدائ د خېمې د خيال ساتلو ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4342, 'Numbers 31:48', 'Numbers', 31, 48, '&nbsp;بيا هغه آفسران موسىٰ له لاړل کومو چې د لښکر مشرى کړې وه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4343, 'Numbers 31:49', 'Numbers', 31, 49, '&nbsp;او موسىٰ ته يې ووئيل، ”صاحِبه، مونږ د جنګ والا کسان وشمېرل کوم چې زمونږ د مشرۍ لاندې وُو او يو سړے هم په کښې کم نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4344, 'Numbers 31:50', 'Numbers', 31, 50, '&nbsp;نو مونږ د سرو زرو کالى، بنګړى، کَړې، ګوتمې، والۍ او هارونه راوړُو چې مونږ هر يو کس اخستى دى. او مونږ يې مالِک خُدائ ته د خپل ژوند په کفاره کښې پېش کړُو، چې هغه مو بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4345, 'Numbers 31:51', 'Numbers', 31, 51, '&nbsp;موسىٰ او اِلى‌عزر ترې نه هغه ټول سرۀ زر او کالى واخستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4346, 'Numbers 31:52', 'Numbers', 31, 52, '&nbsp;د آفسرانو پېش کړے شوې برخه تقريباً دوه سوه کلو وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4347, 'Numbers 31:53', 'Numbers', 31, 53, '&nbsp;چې کوم کسان آفسران نۀ وُو هغوئ هغه لوټ شوے مال د ځان دپاره کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4348, 'Numbers 31:54', 'Numbers', 31, 54, '&nbsp;نو موسىٰ او اِلى‌عزر اِمام هغه سرۀ زر خېمې ته يوړل، چې د بنى اِسرائيلو د يادګيرنې دپاره د مالِک خُدائ په حضور کښې پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4349, 'Numbers 32:1', 'Numbers', 32, 1, '&nbsp;د روبين او جاد قبيلې سره ډېر څاروى وُو. کله چې هغوئ وليدل چې د يعزير او جِلعاد زمکه د څاروو دپاره ښۀ وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4350, 'Numbers 32:2', 'Numbers', 32, 2, '&nbsp;نو هغوئ موسىٰ، اِلى‌عزر او د قوم نورو مشرانو له لاړل او ورته يې ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4351, 'Numbers 32:5', 'Numbers', 32, 5, '&nbsp;کۀ ستاسو خوښه وى نو مونږ له دا زمکه راکړئ چې زمونږ ميراث شى، ځکه چې مونږ ستاسو خِدمتګاران يُو او مونږ مۀ مجبوروئ چې لاړ شُو او د اُردن سيند نه پورې غاړه اوسيږو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4352, 'Numbers 32:6', 'Numbers', 32, 6, '&nbsp;موسىٰ ورته وفرمائيل، ”ستاسو وروڼه اِسرائيليان جنګ له روان دى او تاسو دلته ايسارېږئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4353, 'Numbers 32:7', 'Numbers', 32, 7, '&nbsp;تاسو د بنى اِسرائيلو زړونه ولې راماتوئ چې د اُردن سيند نه پورې وځى او هغه مُلک ته ننوځى چې کوم مالِک خُدائ ورکړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4354, 'Numbers 32:8', 'Numbers', 32, 8, '&nbsp;دغه شان ستاسو پلار نيکۀ هم کړى وُو کله چې ما هغوئ د قادِس برنيع نه ولېږل چې هغه مُلک وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4355, 'Numbers 32:9', 'Numbers', 32, 9, '&nbsp;هغوئ د اسکال وادۍ پورې لاړل او هغه مُلک يې وليدو، خو چې کله هغوئ راواپس شول، نو هغوئ د بنى اِسرائيلو اراده بدله کړه چې هغه مُلک ته ورننه نۀ وځى کوم چې مالِک خُدائ هغوئ له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4356, 'Numbers 32:10', 'Numbers', 32, 10, '&nbsp;مالِک خُدائ په هغه ورځ په قهر وو او يو لوظ يې وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4357, 'Numbers 32:11', 'Numbers', 32, 11, '&nbsp;”دوئ زما په لاره روان نۀ دى، نو زۀ قسم کوم چې کوم خلق د مِصر نه راوتلى دى هغه يو سړے به هم هغه مُلک ته ورننه نۀ وځى چې عُمر يې شل کاله يا د دې نه زيات وى چې د کوم مُلک لوظ ما د اِبراهيم، اِسحاق او د يعقوب سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4358, 'Numbers 32:12', 'Numbers', 32, 12, '&nbsp;خو صرف د يفُنه زوئ کالب قنزى او د نون زوئ يشوَع د زړۀ د اخلاصه په مالِک خُدائ پسې روان وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4359, 'Numbers 32:13', 'Numbers', 32, 13, '&nbsp;مالِک خُدائ بنى اِسرائيلو ته په قهر وو او څلوېښت کاله يې په بيابان کښې سرګردانه کړى وُو تر دې پورې چې هغه ټول نسل مړ شو چا چې مالِک خُدائ نارضا کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4360, 'Numbers 32:14', 'Numbers', 32, 14, '&nbsp;او اوس تاسو د خپل پلار نيکۀ په ځائ يو نوې بد‌کاره نسل راغلى يئ چې د مالِک خُدائ سخت قهر په بنى اِسرائيلو باندې بيا راولئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4361, 'Numbers 32:15', 'Numbers', 32, 15, '&nbsp;د روبين او جاد خلقو کۀ تاسو د هغۀ د لارې نه واوړئ، نو هغه به يو ځل بيا دا ټول خلق په بيابان کښې پرېږدى او تاسو به د هغوئ د تباهۍ ذمه وار يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4362, 'Numbers 32:16', 'Numbers', 32, 16, '&nbsp;هغوئ موسىٰ ته نزدې ورغلل او ورته يې ووئيل، ”اول، مونږ له اجازت راکړه چې دلته د خپلو ګډو دپاره شپول جوړ کړُو او د خپلو ښځو او ماشومانو دپاره ښارونه جوړ کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4363, 'Numbers 32:17', 'Numbers', 32, 17, '&nbsp;بيا به مونږ دې ته تيار يُو چې د خپلو بنى اِسرائيلو سره جنګ له لاړ شُو او حمله وکړُو تر دې پورې چې هغه مُلک ته يې بوځُو چې کوم به د هغوئ وى. نو په هغه دوران کښې به زمونږ ښځې او ماشومان په هغه پَخو ښارونو کښې اوسيږى، دا ښارونه به د هغه مُلک د خلقو نه د حِفاظت دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4364, 'Numbers 32:18', 'Numbers', 32, 18, '&nbsp;مونږ به تر هغه وخت پورې خپلو کورونو ته نۀ راواپس کيږُو چې نورو ټولو بنى اِسرائيلو ته هغه مُلک په ميراث کښې حواله شوے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4365, 'Numbers 32:19', 'Numbers', 32, 19, '&nbsp;مونږ به د اُردن هغه غاړې نه د هغوئ هيڅ جائيداد هم نۀ اخلو، ځکه چې مونږ ته خپله حِصه دلته د اُردن نمرخاتۀ طرف ته مِلاو شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4366, 'Numbers 32:20', 'Numbers', 32, 20, '&nbsp;موسىٰ ورته وفرمائيل، ”کۀ تاسو هم دغه شان کوئ چې څنګه وايئ، نو دلته د مالِک خُدائ په حضور کښې د جنګ دپاره تلو ته تيار شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4367, 'Numbers 32:21', 'Numbers', 32, 21, '&nbsp;ستاسو د جنګ ټول سړى به د اُردن نه پورې وځى او د مالِک خُدائ د حُکم لاندې به زمونږ په دشمن حمله وکړى ترڅو چې مالِک خُدائ هغوئ له شکست ورکړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4368, 'Numbers 32:22', 'Numbers', 32, 22, '&nbsp;او هغه مُلک ونيسى. بيا تاسو راواپس کېدے شئ، ځکه چې تاسو به د مالِک خُدائ او د خپلو بنى اِسرائيلو سره ذمه وارى پوره کړې وى. نو بيا د مالِک خُدائ په نظر کښې دا مُلک ستاسو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4369, 'Numbers 32:23', 'Numbers', 32, 23, '&nbsp;خو کۀ تاسو خپله وعده پوره نۀ کړه، نو زۀ تاسو خبروم چې تاسو به د مالِک خُدائ خِلاف ګناه وکړئ. چې دا غلطى ونۀ کړئ، ګنې تاسو ته به د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4370, 'Numbers 32:24', 'Numbers', 32, 24, '&nbsp;خپل ښارونه جوړ کړئ او د خپلو ګډو دپاره شپول جوړ کړئ، خو چې کومه وعده مو کړې وى هم هغه شان وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4371, 'Numbers 32:25', 'Numbers', 32, 25, '&nbsp;د جاد او د روبين سړو ووئيل، ”صاحِبه، مونږ به هم هغه شان وکړُو چې څنګه تۀ حُکم کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4372, 'Numbers 32:26', 'Numbers', 32, 26, '&nbsp;زمونږ ښځې او ماشومان او زمونږ څاروى او ګډې به دلته د جِلعاد په ښار کښې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4373, 'Numbers 32:27', 'Numbers', 32, 27, '&nbsp;خو د مالِک خُدائ د حُکم لاندې مونږ ټول تيار يُو چې جنګ له لاړ شُو. مونږ به د اُردن نه پورې واوړُو او جنګ به وکړُو، هم هغه شان چې څنګه تا وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4374, 'Numbers 32:28', 'Numbers', 32, 28, '&nbsp;نو موسىٰ اِلى‌عزر، يشوَع او د بنى اِسرائيلو نورو مشرانو له دا حُکم ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4375, 'Numbers 32:29', 'Numbers', 32, 29, '&nbsp;”کۀ د جاد او روبين سړى د اُردن نه پورې وځى چې هغوئ د مالِک خُدائ په حُکم باندې جنګ ته تيار دى او کۀ د هغوئ په مدد سره هغه مُلک فتح کړى، نو بيا هغوئ له د جِلعاد زمکه په ميراث کښې ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4376, 'Numbers 32:30', 'Numbers', 32, 30, '&nbsp;خو کۀ هغوئ د اُردن نه پورې نۀ وځى او ستاسو سره جنګ له لاړ شى، نو هغوئ ته به د زمکې خپله حِصه د کنعان په مُلک کښې ملاويږى، لکه څنګه چې تاسو ته ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4377, 'Numbers 32:31', 'Numbers', 32, 31, '&nbsp;د جاد او روبين کسانو ورته ووئيل، ”صاحِبه، مونږ به هم هغه شان وکړُو چې څنګه مالِک خُدائ حُکم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4378, 'Numbers 32:32', 'Numbers', 32, 32, '&nbsp;د هغۀ د حُکم لاندې به مونږ د کنعان مُلک ته ورواوړُو او جنګ له به لاړ شُو، خو زمونږ ميراث به د اُردن هم دې غاړې ته وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4379, 'Numbers 32:33', 'Numbers', 32, 33, '&nbsp;نو موسىٰ د جاد او روبين او د منسى نيمې قبيلې ته د امورى بادشاه سيحون او د بسن بادشاه عوج ټوله علاقه په حواله کړه، چې په کښې ښارونه او ګېرچاپېره مُلک هم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4380, 'Numbers 32:34', 'Numbers', 32, 34, '&nbsp;د جاد قبيلې د ديبون، عطاروت او د عروعير پاخۀ ښارونه بيا جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4381, 'Numbers 32:35', 'Numbers', 32, 35, '&nbsp;ورسره د عطروت، شوفان، يعزير، يګبها،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4382, 'Numbers 32:36', 'Numbers', 32, 36, '&nbsp;د بيت‌نِمره او د بيت‌هاران ښارونه هم جوړ کړل. د هغې ګېرچاپېره يې دېوالونه جوړ کړل او د خپلو رمو د ساتلو دپاره يې ځايونه هم جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4383, 'Numbers 32:37', 'Numbers', 32, 37, '&nbsp;د روبين قبيلې دا ښارونه بيا جوړ کړل، حسبون، اِلى‌عالى، قِريَتائم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4384, 'Numbers 32:38', 'Numbers', 32, 38, '&nbsp;نبو، بعل معون، (دا نومونه وروستو بدل کړے شول) او سبماه. هغوئ چې کوم ښارونه بيا جوړ کړل نو نوى نومونه ورباندې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4385, 'Numbers 32:39', 'Numbers', 32, 39, '&nbsp;د منسى زوئ مکير قبيلې د جِلعاد په مُلک حمله وکړه او هغه يې ونيولو او هلته چې کوم اموريان وُو هغه يې ترې نه وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4386, 'Numbers 32:40', 'Numbers', 32, 40, '&nbsp;نو موسىٰ د مکير قبيلې له جِلعاد ورکړو او هغوئ هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4387, 'Numbers 32:41', 'Numbers', 32, 41, '&nbsp;د منسى قبيلې، يائير حمله وکړه او څۀ کلى يې ونيول او د ”يائير کلى“ نوم يې ورباندې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4388, 'Numbers 32:42', 'Numbers', 32, 42, '&nbsp;نوبح حمله وکړه او د قنات ښار او د دې کلى يې ونيول او خپل نوم ”نوبح“ يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4389, 'Numbers 33:1', 'Numbers', 33, 1, '&nbsp;بنى اِسرائيلو د لښکرو په شکل کښې په دې مرحلو کښې سفر وکړو او د موسىٰ او هارون په مشرۍ کښې د مِصر نه لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4390, 'Numbers 33:2', 'Numbers', 33, 2, '&nbsp;د مالِک خُدائ په حُکم باندې، موسىٰ به هر ځل د هغه ځائ نوم ليکلو چرته به چې هغوئ خېمې لګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4391, 'Numbers 33:3', 'Numbers', 33, 3, '&nbsp;د کال د وړومبۍ مياشتې په پينځلسمه ورځ اِسرائيليان د مِصر نه لاړل، دا د اول ځل د فسحې اختر پسې ورځ وه. هغوئ د رعمسيس ښار نه زړَور لاړل چې ټولو مِصريانو ورته کتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4392, 'Numbers 33:4', 'Numbers', 33, 4, '&nbsp;چا چې خپل مشران زامن ښخول چې مالِک خُدائ وژلى وُو. ځکه چې مالِک خُدائ د هغوئ د معبودانو سره اِنصاف کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4393, 'Numbers 33:5', 'Numbers', 33, 5, '&nbsp;اِسرائيليان د رعمسيس ښار نه لاړل او په سُکات کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4394, 'Numbers 33:6', 'Numbers', 33, 6, '&nbsp;بيا هغوئ په ايتام کښې خېمې ولګولې چې د صحرا په غاړه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4395, 'Numbers 33:7', 'Numbers', 33, 7, '&nbsp;د هغه ځائ نه هغوئ فى‌هخيروت ته واپس شول، چې د بعل‌صفون نمرخاتۀ په طرف دے او مجدال ته نزدې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4396, 'Numbers 33:8', 'Numbers', 33, 8, '&nbsp;هغوئ د فى‌هخيروت نه لاړل، د سيند نه پورې وتل او د شور صحرا ته وردننه شول، د درېو ورځو مزل نه پس هغوئ په ماره کښې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4397, 'Numbers 33:9', 'Numbers', 33, 9, '&nbsp;د هغې ځائ نه هغوئ ايليم ته لاړل، چرته چې هغوئ خېمې ولګولې، ځکه چې هلته د اوبو دولس چېنې وې او د کجورو اويا ونې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4398, 'Numbers 33:10', 'Numbers', 33, 10, '&nbsp;هغوئ د ايليم نه لاړل او بحرِقُلزم ته نزدې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4399, 'Numbers 33:11', 'Numbers', 33, 11, '&nbsp;بيا هغوئ د بحرِقُلزم نه لاړل او د صين په بيابان کښې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4400, 'Numbers 33:12', 'Numbers', 33, 12, '&nbsp;بيا هغوئ د صين بيابان نه لاړل او په دفقه کښې يې خېمې ولګولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');